function setZoom(v,reset=false){zoom=Math.max(1,Math.min(4,+v||1));const stage=$('#cecV162Stage'),vp=$('#cecV162Viewport');if(stage)stage.style.width=(zoom*100)+'%';if(reset&&vp)vp.scrollTo({left:0,top:0,behavior:'smooth'})}function setStatus(text,kind=''){const e=$('#cecV162Status');if(!e)return;e.textContent=text;e.className='cec-v162-status'+(kind?' '+kind:'')}function updateProgress(){const m=metric(current);if($('#cecV162ProgressText'))$('#cecV162ProgressText').textContent=`${m.done} de ${m.total} lados/tramos`;if($('#cecV162ProgressBar'))$('#cecV162ProgressBar').style.width=m.pct+'%';if($('#cecV162Pct'))$('#cecV162Pct').textContent=m.pct+'%'}function showGeneral(){const c=$('.cec-map-card');if(!c)return;c.classList.remove('cec-v162-mode');c.classList.add('cec-v162-general');setDrawing(false)}function showIndividual(){const c=$('.cec-map-card');if(!c)return;c.classList.add('cec-v162-mode');c.classList.remove('cec-v162-general')}
function loadIndividual(n){if(!ensureUi())return;current=String(n||currentTerritory());showIndividual();setZoom(1,true);setDrawing(false);$('#cecV162Title').textContent='Territorio '+current;updateProgress();renderStrokes();const cached=imageCache[current];if(cached){applyImage(current,cached.src,cached.w,cached.h);return}const fileId=PDF_IDS[current];if(!fileId){setStatus('No se encontró el plano individual de este territorio.','error');return}$('#cecV162Image').removeAttribute('src');setStatus(`Cargando plano original del Territorio ${current}…`);if(window.AndroidBridge&&typeof window.AndroidBridge.loadTerritoryPdf==='function')window.AndroidBridge.loadTerritoryPdf(current,fileId);else setStatus('El plano individual se renderiza dentro del APK Android.','error')}
function applyImage(n,src,w,h){if(String(n)!==current)return;const img=$('#cecV162Image');if(!img)return;img.src=src;img.alt=`Plano individual oficial del Territorio ${n}`;setStatus(`Territorio ${n} · plano individual listo. Puede ampliar, desplazar y dibujar directamente sobre las calles.`,'ok');setTimeout(()=>{renderStrokes();updateProgress()},40)}window.__cecReceiveTerritoryImage=function(n,b64,w,h){const src='data:image/png;base64,'+b64;imageCache[String(n)]={src,w:+w||0,h:+h||0};applyImage(String(n),src,w,h)};window.__cecTerritoryImageError=function(n,msg){if(String(n)!==current)return;setStatus(msg||'No se pudo cargar el plano individual.','error')};
function bindDraw(svg){if(!svg||svg.dataset.v162Bound)return;svg.dataset.v162Bound='1';svg.addEventListener('pointerdown',e=>{if(!drawing)return;e.preventDefault();svg.setPointerCapture?.(e.pointerId);currentStroke=[point(e,svg)];renderStrokes()});svg.addEventListener('pointermove',e=>{if(!drawing||!currentStroke)return;e.preventDefault();const p=point(e,svg),last=currentStroke[currentStroke.length-1];if(Math.hypot(p.x-last.x,p.y-last.y)>.15){currentStroke.push(p);renderStrokes()}});const end=e=>{if(!drawing||!currentStroke)return;e.preventDefault();const pts=currentStroke;currentStroke=null;if(pts.length>2&&Math.hypot(pts[0].x-pts[pts.length-1].x,pts[0].y-pts[pts.length-1].y)>.6)commitStroke(pts);else renderStrokes()};svg.addEventListener('pointerup',end);svg.addEventListener('pointercancel',end)}function point(e,svg){const r=svg.getBoundingClientRect();return{x:Math.max(0,Math.min(100,(e.clientX-r.left)/r.width*100)),y:Math.max(0,Math.min(100,(e.clientY-r.top)/r.height*100))}}function setDrawing(v){drawing=!!v;const svg=$('#cecV162Svg'),btn=$('#cecV162Draw'),vp=$('#cecV162Viewport');svg?.classList.toggle('drawing',drawing);btn?.classList.toggle('active',drawing);if(btn)btn.textContent=drawing?'✓ Finalizar dibujo':'✎ Dibujar realizado';if(vp)vp.style.overflow=drawing?'hidden':'auto';const h=$('#cecV162Help');if(h&&drawing)h.innerHTML='<strong>Modo dibujo activo.</strong> Pase el dedo exactamente por el lado de calle trabajado. Al soltar, podrá indicar qué lado/tramo corresponde para sumarlo al termómetro.'}function straightenStroke(raw){
 const pts=(raw||[]).filter(p=>Number.isFinite(p.x)&&Number.isFinite(p.y));if(pts.length<2)return pts;
 const n=pts.length,mx=pts.reduce((a,p)=>a+p.x,0)/n,my=pts.reduce((a,p)=>a+p.y,0)/n;
 let xx=0,xy=0,yy=0;pts.forEach(p=>{let dx=p.x-mx,dy=p.y-my;xx+=dx*dx;xy+=dx*dy;yy+=dy*dy});
 const angle=.5*Math.atan2(2*xy,xx-yy),ux=Math.cos(angle),uy=Math.sin(angle);
 let lo=Infinity,hi=-Infinity;pts.forEach(p=>{const t=(p.x-mx)*ux+(p.y-my)*uy;lo=Math.min(lo,t);hi=Math.max(hi,t)});
 if(hi-lo<.8)return [pts[0],pts[n-1]];
 const norm=p=>({x:+Math.max(0,Math.min(100,p.x)).toFixed(3),y:+Math.max(0,Math.min(100,p.y)).toFixed(3)});
 return [norm({x:mx+lo*ux,y:my+lo*uy}),norm({x:mx+hi*ux,y:my+hi*uy})];
}
function commitStroke(points){const all=readDraw();all[current]=Array.isArray(all[current])?all[current]:[];const rawPoints=points.map(p=>({x:+p.x.toFixed(3),y:+p.y.toFixed(3)})),straight=straightenStroke(rawPoints);const st={id:Date.now(),points:straight,rawPoints,keys:[],newlyMarked:[],createdAt:new Date().toISOString()};all[current].push(st);writeDraw(all);renderStrokes();openResolver(current,st.id)}function renderStrokes(){const svg=$('#cecV162Svg');if(!svg)return;const preview=currentStroke?straightenStroke(currentStroke):null;const currentLine=svg.querySelector('polyline.current');if(preview&&currentLine){currentLine.setAttribute('points',preview.map(p=>p.x+','+p.y).join(' '));return}const all=readDraw(),arr=Array.isArray(all[current])?all[current]:[];svg.innerHTML=arr.map(st=>`<polyline class="${st.keys?.length?'confirmed':''}" points="${st.points.map(p=>`${p.x},${p.y}`).join(' ')}"></polyline>`).join('')+(preview?`<polyline class="current" points="${preview.map(p=>`${p.x},${p.y}`).join(' ')}"></polyline>`:'')}
function oldDrawingUses(n,k){const old=readJson(OLD_DRAW_KEY,{}),arr=Array.isArray(old[n])?old[n]:[];return arr.some(st=>(st.detected||[]).some(x=>x.key===k)||(st.newlyMarked||[]).includes(k))}function undoStroke(){const all=readDraw(),arr=Array.isArray(all[current])?all[current]:[];if(!arr.length)return;const st=arr.pop();all[current]=arr;writeDraw(all);if(st.newlyMarked?.length){const state=readState();state[current]=state[current]||{};state[current].done=state[current].done||{};st.newlyMarked.forEach(k=>{const still=arr.some(x=>(x.keys||[]).includes(k))||oldDrawingUses(current,k);if(!still)delete state[current].done[k]});state[current].updatedAt=new Date().toISOString();writeState(state)}renderStrokes();refreshTerritory()}function clearStrokes(){const all=readDraw(),arr=Array.isArray(all[current])?all[current]:[];if(!arr.length)return;if(!confirm(`¿Borrar los dibujos del Territorio ${current}? Las marcas ya confirmadas como realizadas permanecerán.`))return;all[current]=[];writeDraw(all);renderStrokes()}
function ensureResolver(){if($('#cecV162Resolve'))return;const r=document.createElement('div');r.id='cecV162Resolve';r.innerHTML=`<div class="cec-v162-sheet" role="dialog" aria-modal="true"><div class="cec-v162-sheet-head"><div><small id="cecV162ResolveMeta">TRAZO REALIZADO</small><strong>¿Qué lado o tramo fue trabajado?</strong></div><button class="cec-v162-close" type="button">×</button></div><input id="cecV162Search" class="cec-v162-search" type="search" placeholder="Buscar manzana o tramo…"><div class="cec-v162-sheet-note">Puede seleccionar uno o varios lados recorridos por este mismo trazo. Solo los seleccionados se suman al termómetro y un mismo lado nunca se cuenta dos veces.</div><div id="cecV162ResolveList" class="cec-v162-resolve-list"></div><div class="cec-v162-sheet-actions"><button id="cecV162OnlyDraw" class="cec-v162-only" type="button">Guardar solo dibujo</button><button id="cecV162Apply" class="cec-v162-apply" type="button" disabled>Sumar al termómetro</button></div></div>`;document.body.appendChild(r);$('.cec-v162-close',r).onclick=closeResolver;r.addEventListener('click',e=>{if(e.target===r)closeResolver()});$('#cecV162Search').addEventListener('input',renderResolver);$('#cecV162Apply').onclick=applyResolved;$('#cecV162OnlyDraw').onclick=closeResolver}function openResolver(n,strokeId){resolving={n:String(n),strokeId};selectedKeys=new Set();$('#cecV162Search').value='';renderResolver();$('#cecV162Resolve').classList.add('open')}function closeResolver(){$('#cecV162Resolve')?.classList.remove('open');resolving=null;selectedKeys=new Set();renderStrokes()}
function renderResolver(){if(!resolving)return;const n=resolving.n,d=DATA[n],state=readState(),done=state[n]?.done||{},q=String($('#cecV162Search')?.value||'').trim().toLowerCase(),root=$('#cecV162ResolveList');$('#cecV162ResolveMeta').textContent=`TERRITORIO ${n} · TRAZO PARA CONFIRMAR`;if(d.type==='tramos')root.innerHTML=d.items.filter(x=>!q||x.toLowerCase().includes(q)).map(item=>{const k=sideKey(item,'territorio'),isDone=!!done[k],sel=selectedKeys.has(k);return`<button class="cec-v162-tramo ${isDone?'done':sel?'sel':''}" data-v162-key="${esc(k)}" ${isDone?'disabled':''}>${isDone?'✓ ':sel?'● ':''}${esc(item)}</button>`}).join('');else root.innerHTML=d.items.filter(x=>!q||x.toLowerCase().includes(q)).map(item=>`<div class="cec-v162-item"><strong>${esc(item)}</strong><div class="cec-v162-sides">${['N','E','S','O'].map(s=>{const k=sideKey(item,s),isDone=!!done[k],sel=selectedKeys.has(k);return`<button class="${isDone?'done':sel?'sel':''}" data-v162-key="${esc(k)}" ${isDone?'disabled':''}>${isDone?'✓ ':sel?'● ':''}${sideName(s)}</button>`}).join('')}</div></div>`).join('');$$('[data-v162-key]',root).forEach(b=>{if(!b.disabled)b.onclick=()=>{const k=b.dataset.v162Key;selectedKeys.has(k)?selectedKeys.delete(k):selectedKeys.add(k);renderResolver()}});const apply=$('#cecV162Apply');apply.disabled=!selectedKeys.size;apply.textContent=selectedKeys.size?`Sumar ${selectedKeys.size} al termómetro`:'Sumar al termómetro'}
function applyResolved(){if(!resolving||!selectedKeys.size)return;const {n,strokeId}=resolving,state=readState(),all=readDraw();state[n]=state[n]||{};state[n].done=state[n].done||{};state[n].labels=state[n].labels||{};const arr=Array.isArray(all[n])?all[n]:[],st=arr.find(x=>String(x.id)===String(strokeId));if(!st)return closeResolver();st.keys=Array.from(new Set([...(st.keys||[]),...selectedKeys]));st.newlyMarked=st.newlyMarked||[];selectedKeys.forEach(k=>{if(!state[n].done[k]){state[n].done[k]=true;st.newlyMarked.push(k)}if(!state[n].labels[k])state[n].labels[k]='Trazado en plano individual'});state[n].updatedAt=new Date().toISOString();writeState(state);writeDraw(all);closeResolver();refreshTerritory();const m=metric(n),h=$('#cecV162Help');if(h)h.innerHTML=`<strong>Trazo confirmado.</strong> Territorio ${n}: ${m.done}/${m.total} lados/tramos · <strong>${m.pct}% realizado</strong>.`}function refreshTerritory(){const n=current;api.select(n,false);setTimeout(()=>{showIndividual();updateProgress();renderStrokes();window.CongElCalafateTerritoriosMapGridV150?.paint?.();window.CongElCalafateTerritoriosReportV162?.refresh?.()},60)}
function wrapSelection(){const select=$('#t15Select');if(select&&!select.dataset.v162){select.dataset.v162='1';select.addEventListener('change',()=>setTimeout(()=>loadIndividual(select.value),90))}const orig=api.select;if(orig&&!api.__v162Wrapped){api.__v162Wrapped=true;api.select=function(n,focus){const r=orig.call(api,String(n),false);if(!window.CongElCalafateV174?.suppressMapReload)setTimeout(()=>loadIndividual(String(n)),60);return r}}}function patchAbout(){const s=$('.about-card strong'),p=$('.about-card p');if(s)s.textContent='Aplicación v1.6.2 · plano individual oficial con dibujo';if(p)p.textContent='Cada territorio abre su propio plano oficial en pantalla amplia. Puede ampliar y dibujar sobre las calles; los lados confirmados alimentan el termómetro.'}
if(ensureUi()){wrapSelection();patchAbout();setTimeout(()=>loadIndividual(currentTerritory()),150)}setTimeout(()=>{ensureUi();wrapSelection();patchAbout()},650);window.CongElCalafateTerritoriosV162={version:VERSION,pdfIds:PDF_IDS,load:loadIndividual,setDrawing,metric,showGeneral};
